
'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useState, type FC, useEffect } from 'react';
import { Menu, X, Zap } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetTrigger, SheetClose, SheetTitle } from '@/components/ui/sheet';
import type { NavItem } from '@/types';
import { cn } from '@/lib/utils';

const navItems: NavItem[] = [
  { label: 'Home', href: '/#hero' },
  { label: 'About', href: '/#about-aeternix' },
  { label: 'Challenges', href: '/#lets-cut-to-the-chase' }, // Updated to combined section ID
  { label: 'Solutions', href: '/#lets-cut-to-the-chase' }, // Updated to combined section ID
  { label: 'Pricing', href: '/#pricing' },
];

const Logo: FC = () => (
  <Link href="/#hero" className="flex items-center gap-2 text-white hover:opacity-90 transition-opacity shrink-0">
    <Zap className="h-7 w-7 text-primary" />
    <span className="text-xl font-bold font-headline">Aeternix</span>
  </Link>
);

const Navbar: FC = () => {
  const pathname = usePathname();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [activeSection, setActiveSection] = useState('hero');

  useEffect(() => {
    const observerOptions = {
      root: null,
      rootMargin: '0px',
      threshold: 0.4, 
    };

    const observerCallback = (entries: IntersectionObserverEntry[]) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    };

    const observer = new IntersectionObserver(observerCallback, observerOptions);
    const sections = document.querySelectorAll('section[id]');
    sections.forEach((section) => observer.observe(section));

    return () => sections.forEach((section) => observer.unobserve(section));
  }, []);


  const navLinkClasses = "px-3 py-1.5 rounded-md text-sm font-medium transition-colors duration-150 ease-in-out text-neutral-300 hover:text-white";
  const activeNavLinkClasses = "text-white font-semibold bg-white/10";
  
  return (
    <header 
      className={cn(
        "fixed top-4 left-1/2 z-50 -translate-x-1/2 w-[95%] sm:w-[90%] md:w-auto md:max-w-screen-lg lg:max-w-screen-xl transition-all duration-300 ease-in-out",
      )}
    >
      <div 
        className="p-[2px] rounded-full bg-gradient-to-r from-primary via-purple-500 to-accent animate-border-flow"
        style={{ backgroundSize: '400% 400%' }}
      >
        <div className={cn(
          "flex h-14 sm:h-[60px] items-center justify-between rounded-full px-4 sm:px-6 shadow-2xl",
          "bg-neutral-900/80 backdrop-blur-lg" 
        )}>
          <Logo />
          
          <nav className="hidden md:flex items-center space-x-2 lg:space-x-2.5">
            {navItems.map((item) => (
              <Link
                key={item.label}
                href={item.href}
                className={cn(
                  navLinkClasses,
                  activeSection === item.href.substring(2) ? activeNavLinkClasses : "" 
                )}
              >
                {item.label}
              </Link>
            ))}
          </nav>
          
          <div className="hidden md:block ml-3 shrink-0">
              <Button 
                asChild 
                size="sm" 
                className="bg-neutral-800 hover:bg-neutral-700 border border-neutral-600/80 text-white rounded-full px-5 py-2.5 text-xs sm:text-sm font-medium hover:shadow-lg hover:shadow-accent/50 hover:shadow-accent/60 transition-all duration-300"
              >
                  <Link href="/#contact">Book Strategy Call</Link>
              </Button>
          </div>

          <div className="md:hidden">
            <Sheet open={isMobileMenuOpen} onOpenChange={setIsMobileMenuOpen}>
              <SheetTrigger asChild>
                <Button variant="ghost" size="icon" className="text-neutral-200 hover:bg-neutral-700/50">
                  <Menu className="h-6 w-6" />
                  <span className="sr-only">Open menu</span>
                </Button>
              </SheetTrigger>
              <SheetContent side="right" className="w-full max-w-xs bg-neutral-900 p-6 flex flex-col text-neutral-100 border-l border-neutral-700">
                  <SheetTitle className="sr-only">Mobile Menu</SheetTitle>
                  <div className="flex items-center justify-between mb-8">
                    <Logo />
                    <SheetClose asChild>
                       <Button variant="ghost" size="icon" className="text-neutral-300 hover:bg-neutral-700/50">
                          <X className="h-6 w-6" />
                          <span className="sr-only">Close menu</span>
                        </Button>
                    </SheetClose>
                  </div>
                  <nav className="flex flex-col space-y-2">
                    {navItems.map((item) => (
                      <SheetClose asChild key={item.label}>
                        <Link
                          href={item.href}
                          className={cn(
                            "text-lg font-medium transition-colors hover:text-primary py-2.5 px-3 rounded-md",
                             activeSection === item.href.substring(2) ? "text-primary bg-primary/10" : "text-neutral-300 hover:bg-neutral-800"
                          )}
                          onClick={() => setIsMobileMenuOpen(false)}
                        >
                          {item.label}
                        </Link>
                      </SheetClose>
                    ))}
                  </nav>
                  <div className="mt-auto pt-8">
                    <Button 
                      asChild 
                      className="w-full bg-primary hover:bg-primary/90 text-primary-foreground hover:shadow-lg hover:shadow-accent/50 transition-all duration-300" 
                      size="lg" 
                      onClick={() => { setIsMobileMenuOpen(false); }}
                    >
                      <Link href="/#contact">
                        Book Strategy Call
                      </Link>
                    </Button>
                  </div>
              </SheetContent>
            </Sheet>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Navbar;
